def scan(name,data,sink):
    for p in pats:
        for enc in ('ascii','utf-16-le','utf-16-be'):
            u=p if enc=='ascii' else p.decode().encode(enc)
            for m in re.finditer(re.escape(u),data):
                sink.append((name,enc,p.decode(),m.start()))
sink=[]
raw=open(PCAP,'rb').read()
scan('PCAP-FILE',raw,sink)
