        try: dec=base64.b64decode(c+b'='*((-len(c))%4))
        except Exception: continue
        scan('httpobj:%s-b64@%d'%(f,m.start()),dec,sink)
print('total hits (excluding generic braces):',len(sink))
for h in sink:
    print(h)
